int is_prime(int n) {
    if (n < 2) return 0;
    for (int d = 2; (long long)d * d <= n; d++) {
        if (n % d == 0) return 0;
    }
    return 1;
}

int main(void) {
    int nums[] = {1, 2, 13, 15, 97};
    for (int i = 0; i < 5; i++) {
        printf("%d\n", is_prime(nums[i]));
    }
    return 0;
}

