typedef struct {
    char **keys;
    long long *vals;
    int len;
    int cap;
} Map;

Map* map_new(int cap) {
    Map *m = malloc(sizeof(Map));
    m->cap = cap;
    m->len = 0;
    m->keys = malloc(sizeof(char*) * cap);
    m->vals = malloc(sizeof(long long) * cap);
    return m;
}

void map_set(Map *m, const char *key, long long val) {
    for (int i = 0; i < m->len; i++) {
        if (strcmp(m->keys[i], key) == 0) {
            m->vals[i] = val;
            return;
        }
    }
    m->keys[m->len] = strdup(key);
    m->vals[m->len] = val;
    m->len++;
}

long long map_get(Map *m, const char *key) {
    for (int i = 0; i < m->len; i++) {
        if (strcmp(m->keys[i], key) == 0) return m->vals[i];
    }
    return 0;
}

int main(void) {
    Map *m = map_new(8);
    map_set(m, "a", 10);
    map_set(m, "b", 20);
    map_set(m, "c", 30);
    map_set(m, "d", 40);
    map_set(m, "e", 50);

    const char *order[] = {"a", "b", "c", "d", "e"};
    for (int i = 0; i < 5; i++) {
        printf("%lld\n", map_get(m, order[i]));
    }
    return 0;
}

