#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Minimal JSON library emulation for the AIC task.
 * This C program builds an object with:
 *   "greeting" = "hi"
 *   "n"        = 42
 *   "list"     = [1,2,3]
 * Then stringifies, re-parses, and prints:
 *   hi
 *   42
 *   3
 */

typedef struct JsonValue JsonValue;

enum JsonType {
    JSON_NULL,
    JSON_BOOL,
    JSON_INT,
    JSON_STR,
    JSON_ARR,
    JSON_OBJ
};

struct JsonValue {
    enum JsonType type;
    int int_val;
    int bool_val;
    char *str_val;

    JsonValue **arr;
    int arr_len;
    int arr_cap;

    char **obj_keys;
    JsonValue **obj_vals;
    int obj_len;
    int obj_cap;
};

static JsonValue *json_new(enum JsonType type) {
    JsonValue *v = (JsonValue *)calloc(1, sizeof(JsonValue));
    if (!v) {
        fprintf(stderr, "allocation failed\n");
        exit(1);
    }
    v->type = type;
    return v;
}

static JsonValue *json_null(void) {
    return json_new(JSON_NULL);
}

static JsonValue *json_bool(int b) {
    JsonValue *v = json_new(JSON_BOOL);
    v->bool_val = b ? 1 : 0;
    return v;
}

static JsonValue *json_int(int n) {
    JsonValue *v = json_new(JSON_INT);
    v->int_val = n;
    return v;
}

static JsonValue *json_str(const char *s) {
    JsonValue *v = json_new(JSON_STR);
    v->str_val = strdup(s);
    if (!v->str_val) {
        fprintf(stderr, "allocation failed\n");
        exit(1);
    }
    return v;
}

static JsonValue *json_arr(void) {
    return json_new(JSON_ARR);
}

static JsonValue *json_obj(void) {
    return json_new(JSON_OBJ);
}

static void json_arr_push(JsonValue *arr, JsonValue *v) {
    if (arr->arr_len >= arr->arr_cap) {
        int newcap = arr->arr_cap == 0 ? 4 : arr->arr_cap * 2;
        JsonValue **na = (JsonValue **)realloc(arr->arr, (size_t)newcap * sizeof(JsonValue *));
        if (!na) {
            fprintf(stderr, "allocation failed\n");
            exit(1);
        }
        arr->arr = na;
        arr->arr_cap = newcap;
    }
    arr->arr[arr->arr_len++] = v;
}

static void json_obj_set(JsonValue *obj, const char *key, JsonValue *v) {
    if (obj->obj_len >= obj->obj_cap) {
        int newcap = obj->obj_cap == 0 ? 4 : obj->obj_cap * 2;
        char **nk = (char **)realloc(obj->obj_keys, (size_t)newcap * sizeof(char *));
        JsonValue **nv = (JsonValue **)realloc(obj->obj_vals, (size_t)newcap * sizeof(JsonValue *));
        if (!nk || !nv) {
            fprintf(stderr, "allocation failed\n");
            exit(1);
        }
        obj->obj_keys = nk;
        obj->obj_vals = nv;
        obj->obj_cap = newcap;
    }
    obj->obj_keys[obj->obj_len] = strdup(key);
    if (!obj->obj_keys[obj->obj_len]) {
        fprintf(stderr, "allocation failed\n");
        exit(1);
    }
    obj->obj_vals[obj->obj_len] = v;
    obj->obj_len++;
}

static JsonValue *json_obj_get(JsonValue *obj, const char *key) {
    for (int i = 0; i < obj->obj_len; i++) {
        if (strcmp(obj->obj_keys[i], key) == 0) {
            return obj->obj_vals[i];
        }
    }
    return NULL;
}

static void json_stringify_rec(JsonValue *v, char **buf, size_t *len, size_t *cap) {
    char tmp[64];
    switch (v->type) {
        case JSON_NULL:
            snprintf(tmp, sizeof(tmp), "null");
            break;
        case JSON_BOOL:
            snprintf(tmp, sizeof(tmp), "%s", v->bool_val ? "true" : "false");
            break;
        case JSON_INT:
            snprintf(tmp, sizeof(tmp), "%d", v->int_val);
            break;
        case JSON_STR: {
            size_t need = strlen(v->str_val) * 2 + 3;
            if (*len + need > *cap) {
                *cap = (*len + need) * 2;
                *buf = (char *)realloc(*buf, *cap);
                if (!*buf) {
                    fprintf(stderr, "allocation failed\n");
                    exit(1);
                }
            }
            (*buf)[(*len)++] = '"';
            for (const char *p = v->str_val; *p; p++) {
                if (*p == '"' || *p == '\\') {
                    (*buf)[(*len)++] = '\\';
                }
                (*buf)[(*len)++] = *p;
            }
            (*buf)[(*len)++] = '"';
            (*buf)[*len] = '\0';
            return;
        }
        case JSON_ARR: {
            snprintf(tmp, sizeof(tmp), "[");
            if (*len + 2 > *cap) {
                *cap = (*cap + 2) * 2;
                *buf = (char *)realloc(*buf, *cap);
                if (!*buf) {
                    fprintf(stderr, "allocation failed\n");
                    exit(1);
                }
            }
            (*buf)[(*len)++] = '[';
            for (int i = 0; i < v->arr_len; i++) {
                if (i > 0) {
                    (*buf)[(*len)++] = ',';
                }
                json_stringify_rec(v->arr[i], buf, len, cap);
            }
            (*buf)[(*len)++] = ']';
            (*buf)[*len] = '\0';
            return;
        }
        case JSON_OBJ: {
            (*buf)[(*len)++] = '{';
            for (int i = 0; i < v->obj_len; i++) {
                if (i > 0) {
                    (*buf)[(*len)++] = ',';
                }
                JsonValue keyv;
                keyv.type = JSON_STR;
                keyv.str_val = v->obj_keys[i];
                json_stringify_rec(&keyv, buf, len, cap);
                (*buf)[(*len)++] = ':';
                json_stringify_rec(v->obj_vals[i], buf, len, cap);
            }
            (*buf)[(*len)++] = '}';
            (*buf)[*len] = '\0';
            return;
        }
    }
    if (*len + strlen(tmp) + 1 > *cap) {
        *cap = (*len + strlen(tmp) + 1) * 2;
        *buf = (char *)realloc(*buf, *cap);
        if (!*buf) {
            fprintf(stderr, "allocation failed\n");
            exit(1);
        }
    }
    memcpy(*buf + *len, tmp, strlen(tmp));
    *len += strlen(tmp);
    (*buf)[*len] = '\0';
}

static char *json_stringify(JsonValue *v) {
    size_t cap = 64;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) {
        fprintf(stderr, "allocation failed\n");
        exit(1);
    }
    buf[0] = '\0';
    json_stringify_rec(v, &buf, &len, &cap);
    return buf;
}

/* Simple recursive-descent JSON parser */
static const char *parse_ws(const char *p) {
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') {
        p++;
    }
    return p;
}

static JsonValue *parse_value(const char **pp);

static JsonValue *parse_string(const char **pp) {
    const char *p = *pp;
    if (*p != '"') {
        fprintf(stderr, "expected string\n");
        exit(1);
    }
    p++;
    size_t cap = 32;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) {
        fprintf(stderr, "allocation failed\n");
        exit(1);
    }
    while (*p && *p != '"') {
        char c = *p;
        if (c == '\\') {
            p++;
            if (!*p) {
                free(buf);
                fprintf(stderr, "unterminated escape\n");
                exit(1);
            }
            switch (*p) {
                case '"': c = '"'; break;
                case '\\': c = '\\'; break;
                case '/': c = '/'; break;
                case 'b': c = '\b'; break;
                case 'f': c = '\f'; break;
                case 'n': c = '\n'; break;
                case 'r': c = '\r'; break;
                case 't': c = '\t'; break;
                default: c = *p; break;
            }
        }
        if (len + 1 >= cap) {
            cap *= 2;
            char *nb = (char *)realloc(buf, cap);
            if (!nb) {
                free(buf);
                fprintf(stderr, "allocation failed\n");
                exit(1);
            }
            buf = nb;
        }
        buf[len++] = c;
        p++;
    }
    if (*p != '"') {
        free(buf);
        fprintf(stderr, "unterminated string\n");
        exit(1);
    }
    p++;
    buf[len] = '\0';
    JsonValue *v = json_str(buf);
    free(buf);
    *pp = p;
    return v;
}

static JsonValue *parse_number(const char **pp) {
    const char *p = *pp;
    int sign = 1;
    if (*p == '-') {
        sign = -1;
        p++;
    }
    int n = 0;
    while (*p >= '0' && *p <= '9') {
        n = n * 10 + (*p - '0');
        p++;
    }
    JsonValue *v = json_int(sign * n);
    *pp = p;
    return v;
}

static JsonValue *parse_value(const char **pp) {
    const char *p = parse_ws(*pp);
    if (*p == '{') {
        p++;
        JsonValue *obj = json_obj();
        p = parse_ws(p);
        if (*p == '}') {
            p++;
            *pp = p;
            return obj;
        }
        while (1) {
            p = parse_ws(p);
            JsonValue *key = parse_string(&p);
            p = parse_ws(p);
            if (*p != ':') {
                fprintf(stderr, "expected ':'\n");
                exit(1);
            }
            p++;
            JsonValue *val = parse_value(&p);
            json_obj_set(obj, key->str_val, val);
            p = parse_ws(p);
            if (*p == ',') {
                p++;
                continue;
            }
            if (*p == '}') {
                p++;
                break;
            }
            fprintf(stderr, "expected ',' or '}'\n");
            exit(1);
        }
        *pp = p;
        return obj;
    }
    if (*p == '[') {
        p++;
        JsonValue *arr = json_arr();
        p = parse_ws(p);
        if (*p == ']') {
            p++;
            *pp = p;
            return arr;
        }
        while (1) {
            JsonValue *val = parse_value(&p);
            json_arr_push(arr, val);
            p = parse_ws(p);
            if (*p == ',') {
                p++;
                continue;
            }
            if (*p == ']') {
                p++;
                break;
            }
            fprintf(stderr, "expected ',' or ']'\n");
            exit(1);
        }
        *pp = p;
        return arr;
    }
    if (*p == '"') {
        JsonValue *v = parse_string(&p);
        *pp = p;
        return v;
    }
    if (*p == '-' || (*p >= '0' && *p <= '9')) {
        JsonValue *v = parse_number(&p);
        *pp = p;
        return v;
    }
    if (strncmp(p, "true", 4) == 0) {
        p += 4;
        *pp = p;
        return json_bool(1);
    }
    if (strncmp(p, "false", 5) == 0) {
        p += 5;
        *pp = p;
        return json_bool(0);
    }
    if (strncmp(p, "null", 4) == 0) {
        p += 4;
        *pp = p;
        return json_null();
    }
    fprintf(stderr, "unexpected character '%c'\n", *p);
    exit(1);
}

static JsonValue *json_parse(const char *s) {
    const char *p = s;
    JsonValue *v = parse_value(&p);
    return v;
}

int main(void) {
    /* Build the object */
    JsonValue *obj = json_obj();
    json_obj_set(obj, "greeting", json_str("hi"));
    json_obj_set(obj, "n", json_int(42));

    JsonValue *list = json_arr();
    json_arr_push(list, json_int(1));
    json_arr_push(list, json_int(2));
    json_arr_push(list, json_int(3));
    json_obj_set(obj, "list", list);

    /* Stringify */
    char *s = json_stringify(obj);

    /* Parse back */
    JsonValue *parsed = json_parse(s);

    JsonValue *greeting = json_obj_get(parsed, "greeting");
    JsonValue *n = json_obj_get(parsed, "n");
    JsonValue *parsed_list = json_obj_get(parsed, "list");

    /* Print results */
    printf("%s\n", greeting->str_val);
    printf("%d\n", n->int_val);
    printf("%d\n", parsed_list->arr_len);

    free(s);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *buffer;
    long offset;
    long cap;
} Arena;

Arena *arena_new(long cap) {
    Arena *a = (Arena *)malloc(sizeof(Arena));
    a->buffer = (char *)calloc(cap + 1, 1);
    a->offset = 0;
    a->cap = cap;
    return a;
}

char *arena_alloc(Arena *a, long bytes) {
    char *p = a->buffer + a->offset;
    a->offset += bytes;
    return p;
}

void arena_reset(Arena *a) {
    a->offset = 0;
}

int main(void) {
    Arena *a = arena_new(1024);

    arena_alloc(a, 4);
    arena_alloc(a, 8);
    arena_alloc(a, 16);

    long offset_after_alloc = a->offset;

    arena_reset(a);

    printf("%ld\n", a->offset);

    free(a->buffer);
    free(a);
    return 0;
}

