#include <stdio.h>
#include <string.h>

int main(void) {
    const char *content = "Hello AIC benchmark input line";
    const char *path = "bench_in.txt";

    FILE *f = fopen(path, "w");
    if (!f) {
        printf("0\n");
        return 0;
    }
    fwrite(content, 1, strlen(content), f);
    fclose(f);

    FILE *r = fopen(path, "rb");
    if (!r) {
        printf("0\n");
        return 0;
    }
    fseek(r, 0, SEEK_END);
    long size = ftell(r);
    fseek(r, 0, SEEK_SET);

    char buf[256];
    size_t nread = fread(buf, 1, sizeof(buf) - 1, r);
    fclose(r);
    buf[nread] = '\0';

    int match = (size == (long)strlen(content)) &&
                (nread == strlen(content)) &&
                (strcmp(buf, content) == 0);

    printf("%d\n", match ? 1 : 0);
    return 0;
}

